<script>
const toolData={"Personal Tax": {"category": "Tax", "details": "The personal income tax experience, designed around clarity."}, "Corporate Tax": {"category": "Tax", "details": "Structured corporate tax assessment and planning."}, "TDS & VDS": {"category": "Tax", "details": "Understand deductions before they become surprises."}, "VAT Calculator": {"category": "Tax", "details": "A considered way to approach VAT calculations."}, "Mushak 6.3": {"category": "VAT", "details": "A cleaner foundation for preparing and tracking invoices."}, "VAT Return": {"category": "VAT", "details": "An organized approach to periodic VAT returns."}, "Income Tax Act": {"category": "Research", "details": "Explore tax law through an easier reading experience."}, "AI Law Search": {"category": "Research", "details": "A future knowledge assistant for Bangladesh tax law."}, "Circulars & SRO": {"category": "Research", "details": "Keep circulars, orders and notices close at hand."}, "Deadline Tracker": {"category": "Tax", "details": "A clear view of important filing milestones."}, "Document Vault": {"category": "Workspace", "details": "Organize records in a thoughtful client workspace."}, "Virtual CFO": {"category": "Workspace", "details": "Bring financial oversight and decision support together."}};
function closeMenus(){document.dispatchEvent(new Event('df:close-nav'));}
document.querySelectorAll('[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{let v=btn.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{let a=b===btn;b.classList.toggle('active',a);b.setAttribute('aria-pressed',String(a))});document.querySelectorAll('.product').forEach(el=>el.hidden=v!=='All'&&el.dataset.kind!==v)}));
function openDialog(id){let d=document.getElementById(id);if(!d.open)d.showModal()}
document.querySelectorAll('[data-title],[data-preview],[data-service]').forEach(el=>el.addEventListener('click',()=>{let name=el.dataset.title||el.dataset.preview||el.dataset.service;document.getElementById('featureTitle').textContent=name;document.getElementById('featureDesc').textContent=toolData[name]?.details || (name==='Client Services'?'For client account and document support, contact our team.':'We are introducing digital services in stages. Please contact DhakaFin for currently available advisory support.');openDialog('featureDialog')}));
document.querySelectorAll('[data-contact]').forEach(el=>el.addEventListener('click',()=>{closeMenus();openDialog('contactDialog')}));
document.querySelectorAll('[data-close]').forEach(el=>el.addEventListener('click',()=>el.closest('dialog').close()));document.querySelectorAll('dialog').forEach(el=>el.addEventListener('click',e=>{if(e.target===el)el.close()}));
document.querySelectorAll('[data-example]').forEach(el=>el.addEventListener('click',()=>{const inp=document.getElementById('aiInput');inp.value=el.dataset.example;document.getElementById('aiForm')?.dispatchEvent(new Event('submit',{cancelable:true,bubbles:true}));}));
document.getElementById('aiForm').addEventListener('submit',e=>{e.preventDefault();let el=document.getElementById('aiResult');el.classList.add('show');el.innerHTML='<strong>Tax research guidance</strong>AI-assisted search is being developed. For a reliable interpretation, consult the official law and speak with our advisory team.'});
const modes={Personal:{title:'Personal overview',labels:['Documents','Tasks','Readiness'],values:['12 Files','3 Open','On track'],rows:['Tax return preparation','Supporting documents','Advisory updates']},Business:{title:'Business overview',labels:['Records','Reviews','Status'],values:['24 Files','5 Open','In review'],rows:['Monthly compliance','Financial reporting','Advisory priorities']}};
document.querySelectorAll('[data-mode]').forEach(btn=>btn.addEventListener('click',()=>{let d=modes[btn.dataset.mode];document.querySelectorAll('[data-mode]').forEach(b=>{let s=b===btn;b.classList.toggle('selected',s);b.setAttribute('aria-pressed',String(s))});document.getElementById('workTitle').textContent=d.title;for(let i=1;i<=3;i++){document.getElementById('wLabel'+i).textContent=d.labels[i-1];document.getElementById('wValue'+i).textContent=d.values[i-1];document.getElementById('wRow'+i).textContent=d.rows[i-1]}}));
document.getElementById('contactForm').addEventListener('submit',e=>{
 e.preventDefault();if(!e.currentTarget.reportValidity())return;
 const name=document.getElementById('contactName').value.trim();
 const replyTo=document.getElementById('contactEmail').value.trim();
 const message=document.getElementById('contactMessage').value.trim();
 const mailBody=['Name: '+name,'Email: '+replyTo,'Enquiry: '+message].join('\n');
 document.getElementById('contactStatus').textContent='Your email application should open. Please review and send; your enquiry is not sent automatically.';
 location.href='mailto:hello.sohan@outlook.com?subject='+encodeURIComponent('DhakaFin website enquiry')+'&body='+encodeURIComponent(mailBody);
});
</script>
